import{_ as e,o as t,c as r,O as n}from"./chunks/framework.db831a78.js";const h=JSON.parse('{"title":"Spring 全家桶","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/04-Spring全家桶.md","filePath":"interview/后端/Java/04-Spring全家桶.md","lastUpdated":1788851914000}'),a={name:"interview/后端/Java/04-Spring全家桶.md"};function s(i,o,p,c,d,l){return t(),r("div",null,o[0]||(o[0]=[n('<h1 id="spring-全家桶" tabindex="-1">Spring 全家桶 <a class="header-anchor" href="#spring-全家桶" aria-label="Permalink to &quot;Spring 全家桶&quot;">​</a></h1><blockquote><p><strong>怎么用这份笔记</strong></p><ul><li>分级：<code>★★★ 必须吃透</code> / <code>★★☆ 了解即可（记结论就行）</code> / <code>★☆☆ 可以跳过（一句话看一眼）</code></li><li>【简历亮点，高频追问】：简历里写过的技术，面试官会顺着往下挖，这段必须能展开讲</li><li>每个考点固定三段：<strong>通俗理解 → 我的项目关联 → 面试答题话术</strong></li><li>「我的项目关联」里的坑分两种，别搞混： <ul><li>写**「线上」**= 真实发生过的问题，可以直接讲现象和修复</li><li>写**「通用坑」<strong>= 经典坑 / 资料里学到的，我们项目没实际踩到，面试时</strong>别说成自己踩过**</li></ul></li></ul></blockquote><hr><h2 id="_1-ioc-与-di-★★★" tabindex="-1">1. IOC 与 DI ★★★ <a class="header-anchor" href="#_1-ioc-与-di-★★★" aria-label="Permalink to &quot;1. IOC 与 DI ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> IOC 是思想：对象的创建和依赖由「业务代码自己 new」反转给 Spring 容器管。DI 是实现手段：容器通过构造器 / setter / 字段把依赖塞进来。好处是解耦、好测试（能注入 mock）。注入方式优先构造器（依赖不可变、能暴露循环依赖、方便测试），字段注入（@Autowired 直接标在字段上）不推荐，因为它隐藏了依赖、单测时只能靠反射。</p><p><strong>我的项目关联</strong> 我们所有服务都是 SpringBoot，Service 之间全靠构造器注入。后台管理服务（yld-admin-service）和 App 服务（yld-app-service）里都是这么写的，不写 <code>new</code>，也好写单测。</p><p><strong>面试答题话术</strong> 「IOC 是思想，DI 是实现。好处是解耦和好测试。注入方式我优先构造器注入，因为依赖是 final 不可变、循环依赖能早点暴露、单测直接 new 就行；字段注入我不用，隐藏依赖还不好测。项目里 Service 全是构造器注入。」</p><hr><h2 id="_2-beanfactory-与-applicationcontext-★★☆" tabindex="-1">2. BeanFactory 与 ApplicationContext ★★☆ <a class="header-anchor" href="#_2-beanfactory-与-applicationcontext-★★☆" aria-label="Permalink to &quot;2. BeanFactory 与 ApplicationContext ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> BeanFactory 是最底层容器，懒加载，getBean 时才创建，功能少。ApplicationContext 继承它，启动时就把单例 Bean 全建好（饿加载），还提供国际化、事件发布、资源加载、AOP 等。生产上用的都是 ApplicationContext。</p><p><strong>我的项目关联</strong> 记结论：平时说的 Spring 容器就是 ApplicationContext，SpringBoot 里也是它。启动慢一点但换来实时可用，这对我们网关这种启动后要立刻扛流量的服务是好事。</p><p><strong>面试答题话术</strong> 「BeanFactory 是底层接口，懒加载、功能少；ApplicationContext 继承它，启动就预实例化单例，还多了事件、国际化、资源加载这些。生产用 ApplicationContext，SpringBoot 里内置的就是它。」</p><hr><h2 id="_3-bean-生命周期-★★★" tabindex="-1">3. Bean 生命周期 ★★★ <a class="header-anchor" href="#_3-bean-生命周期-★★★" aria-label="Permalink to &quot;3. Bean 生命周期 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 八步：实例化（构造器）→ 属性注入 → Aware 接口回调 → BeanPostProcessor 前置 → 初始化（@PostConstruct → afterPropertiesSet → init-method）→ BeanPostProcessor 后置（AOP 代理就在这一步生成）→ 使用 → 销毁（@PreDestroy → destroy → destroy-method）。重点记两件事：@PostConstruct 比 afterPropertiesSet 先执行；AOP 代理在「后置处理」这一环产生。</p><p><strong>我的项目关联</strong> 我们用它做初始化：比如网关启动时要把「协议命令处理器」注册到一张表里，就写在 @PostConstruct 或 afterPropertiesSet 里。<strong>不用深挖 BeanPostProcessor 内部源码</strong>，记住它是「Bean 初始化的前后钩子、AOP 靠它」就够了。</p><p><strong>面试答题话术</strong> 「生命周期核心是：实例化、属性注入、Aware、初始化前后两个 BeanPostProcessor、使用、销毁。两个高频点：@PostConstruct 比 InitializingBean 的 afterPropertiesSet 早；AOP 代理是在 postProcessAfterInitialization 里生成的。我用它做启动初始化，比如把协议处理器注册到本地表。」</p><hr><h2 id="_4-bean-作用域-★★☆" tabindex="-1">4. Bean 作用域 ★★☆ <a class="header-anchor" href="#_4-bean-作用域-★★☆" aria-label="Permalink to &quot;4. Bean 作用域 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 默认 singleton（容器里一个），prototype 每次拿新的，Web 里还有 request/session/application。有个坑：prototype Bean 注入到 singleton Bean 里，只会注入一次，之后不会每次新建——想每次拿新的得用 <code>@Lookup</code> 或注入 <code>ObjectFactory</code>。</p><p><strong>我的项目关联</strong> 我们 99% 是单例，无状态的 Service 都用默认单例。prototype 基本不用，所以那个注入坑属于「通用坑」，没实际踩过，知道有这回事就行。</p><p><strong>面试答题话术</strong> 「默认单例，prototype 每次新建。坑是 prototype 注入到单例里只注入一次，要每次新实例得用 @Lookup 或 ObjectFactory。项目里几乎全用单例。」</p><hr><h2 id="_5-单例-bean-的线程安全-★★★-【简历亮点-高频追问】" tabindex="-1">5. 单例 Bean 的线程安全 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_5-单例-bean-的线程安全-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;5. 单例 Bean 的线程安全 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 单例 Bean 只要「无状态」（只有方法、没有可变的成员变量）就是线程安全的。一旦在单例 Bean 里放了共享可变字段（比如一个计数器、一个 Map 当本地缓存），多线程访问就出问题。解决办法：尽量无状态；要状态就用 ThreadLocal 隔离，或者用并发容器 / 原子类；再不行才改 prototype。Controller 默认单例，只要不写可变成员变量就安全，方法里的局部变量天然安全。</p><p><strong>我的项目关联</strong><strong>这条我特别有体会。</strong> 网关里有些处理器 Bean 是单例的，早期有人在里面写了 <code>private Map</code> 当本地缓存，多线程一跑数据就乱了（现象是「同一个设备的状态莫名其妙被覆盖」），后来改成 ConcurrentHashMap 或者干脆挪到 Redis 才解决。<strong>这是真实踩过的坑</strong>，也是我现在写单例 Bean 的铁律：不放可变字段。</p><p><strong>面试答题话术</strong> 「单例 Bean 只要无状态就线程安全。我踩过这个坑——网关里一个单例处理器里放了普通 HashMap 当缓存，多线程下数据互相覆盖，后来换成 ConcurrentHashMap 或者直接放 Redis。所以我的原则是：单例 Bean 不放共享可变字段，要状态就用并发容器或 ThreadLocal。Controller 单例安全也是同一个道理，别写成员变量。」</p><hr><h2 id="_6-循环依赖与三级缓存-★★☆-记结论即可" tabindex="-1">6. 循环依赖与三级缓存 ★★☆（记结论即可） <a class="header-anchor" href="#_6-循环依赖与三级缓存-★★☆-记结论即可" aria-label="Permalink to &quot;6. 循环依赖与三级缓存 ★★☆（记结论即可）&quot;">​</a></h2><p><strong>通俗理解</strong> Spring 用三级缓存解决「单例 + 字段/setter 注入」的循环依赖：一级放成品 Bean，二级放提前暴露的半成品，三级放能生成半成品的 ObjectFactory（AOP 场景下保证拿到的是代理）。<strong>结论就三句</strong>：只能解决单例 + setter/字段注入；构造器注入的循环依赖解决不了（直接抛 BeanCurrentlyInCreationException）；SpringBoot 2.6 之后默认禁止循环依赖，要用得手动开。不用去背三级缓存的逐行流转。</p><p><strong>我的项目关联</strong> 现在基本不让自己写出循环依赖——SpringBoot 2.6 之后默认就报错了。我们遇到时的处理不是去开开关，而是直接重构：把公共逻辑抽到第三个 Bean 里。这属于设计问题，别靠框架兜。</p><p><strong>面试答题话术</strong> 「三级缓存解决的是单例加 setter/字段注入的循环依赖，一级是成品、二级是提前暴露的半成品、三级是生成半成品的工厂。结论最重要：构造器注入的循环依赖解决不了，而且 SpringBoot 2.6 之后默认就禁止循环依赖了。我项目里遇到就直接重构抽公共 Bean，不靠框架兜底。」</p><hr><h2 id="_7-aop-原理-jdk-动态代理-vs-cglib-★★★-【简历亮点-高频追问】" tabindex="-1">7. AOP 原理（JDK 动态代理 vs CGLIB）★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_7-aop-原理-jdk-动态代理-vs-cglib-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;7. AOP 原理（JDK 动态代理 vs CGLIB）★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> AOP 就是把日志、事务、权限这些「横切逻辑」从业务代码里抽出来，用代理在方法前后织进去。两种实现：JDK 动态代理基于接口（<code>Proxy.newProxyInstance</code>），要求目标有接口；CGLIB 基于继承生成子类，不需要接口，但 final 类/方法代理不了。Spring 默认「有接口用 JDK、没接口用 CGLIB」，SpringBoot 2.x 起默认直接 CGLIB。</p><p><strong>我的项目关联</strong> 我们用它做统一日志、接口耗时统计、权限校验，还有最关键的——声明式事务（@Transactional 本质就是 AOP）。<strong>这里有个认知要点</strong>：因为事务是 AOP 实现的，所以它依赖「走代理」，同一类内部 <code>this.方法()</code> 调用不走代理、事务就会失效。</p><p><strong>面试答题话术</strong> 「AOP 是用代理把横切逻辑织进方法前后。JDK 代理基于接口，CGLIB 基于继承、不需要接口但不能代理 final。SpringBoot 现在默认用 CGLIB。项目里事务、日志、权限都是 AOP 做的。关键认知是：事务靠代理生效，所以 this 自调用会失效。」</p><hr><h2 id="_8-transactional-失效场景-★★★-【简历亮点-高频追问】" tabindex="-1">8. @Transactional 失效场景 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_8-transactional-失效场景-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;8. @Transactional 失效场景 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 最常见六种失效：① 方法不是 public（事务只对 public 生效）；② 同类内部 <code>this.xxx()</code> 自调用，不走代理；③ 异常被自己 catch 吞了，事务感知不到；④ 抛的是受检异常，默认只回滚 RuntimeException/Error，要加 <code>rollbackFor = Exception.class</code>；⑤ 方法所在类不是 Spring Bean；⑥ 数据库引擎不支持事务（如 MyISAM）。自调用的三种解法：注入自己、<code>AopContext.currentProxy()</code>、或者把方法抽到另一个 Bean。</p><p><strong>我的项目关联</strong><strong>这个坑我们在订单、支付相关逻辑上确实遇到过。</strong> 现象是「内部方法报错了但数据没回滚」，排查发现是同类里的 <code>this.xxx()</code> 调用绕过了代理。修复就是把这段逻辑抽到独立的 Service Bean，或者注入自身调。现在团队规范是：<strong>事务方法绝不和调用方放同一个类</strong>。</p><p><strong>面试答题话术</strong> 「失效主要有六种：非 public、自调用、异常被吞、受检异常不回滚、类不是 Bean、引擎不支持事务。最常见的是自调用，因为事务是代理实现的，this 调用不走代理。我项目里真遇到过——内部方法报错但没回滚，后来把逻辑抽到独立 Bean 解决。我的规范是：事务方法不和调用方放一个类，受检异常一定加 rollbackFor。」</p><hr><h2 id="_9-事务传播行为-★★★" tabindex="-1">9. 事务传播行为 ★★★ <a class="header-anchor" href="#_9-事务传播行为-★★★" aria-label="Permalink to &quot;9. 事务传播行为 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 七种，重点记两个：REQUIRED（默认，有事务就加入，没有就新建，事务内任何一处回滚全体回滚）；REQUIRES_NEW（永远新建独立事务，把当前事务挂起，内层回滚不影响外层）。其余知道名字即可：SUPPORTS、NOT_SUPPORTED、MANDATORY、NEVER、NESTED。</p><p><strong>我的项目关联</strong> 最典型的用法是「主流程失败要回滚，但操作日志必须记下来」——日志那块就用 REQUIRES_NEW，保证主事务回滚了日志还在。对账、订单主流程用默认 REQUIRED。</p><p><strong>面试答题话术</strong> 「七种传播行为，重点就两个：REQUIRED 是默认，共用事务，一处回滚全回滚；REQUIRES_NEW 是独立事务，挂起外层，内层回滚不影响外层。项目里操作日志用 REQUIRES_NEW，保证主事务回滚了日志还在，主流程用默认 REQUIRED。」</p><hr><h2 id="_10-springboot-自动配置原理-★★★" tabindex="-1">10. SpringBoot 自动配置原理 ★★★ <a class="header-anchor" href="#_10-springboot-自动配置原理-★★★" aria-label="Permalink to &quot;10. SpringBoot 自动配置原理 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><code>@SpringBootApplication</code> = <code>@SpringBootConfiguration</code> + <code>@EnableAutoConfiguration</code> + <code>@ComponentScan</code>。<code>@EnableAutoConfiguration</code> 通过 <code>@Import(AutoConfigurationImportSelector)</code> 去读 <code>META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports</code>（2.7 之后的新位置，老版本才是 <code>spring.factories</code>），拿到一堆自动配置类，再用 <code>@ConditionalOnClass</code>、<code>@ConditionalOnMissingBean</code>、<code>@ConditionalOnProperty</code> 判断要不要生效，从而实现「约定大于配置」。</p><p><strong>我的项目关联</strong> 我们写过内部 starter 封装公共能力（比如统一异常、日志、埋点），就是照着这个套路：写配置类 + 在 imports 文件里注册 + 条件注解，业务服务引依赖就自动生效。<strong>注意</strong>：现在面试要答 <code>AutoConfiguration.imports</code>，老说 <code>spring.factories</code> 会显旧。</p><p><strong>面试答题话术</strong> 「@SpringBootApplication 拆开是配置类、开启自动配置、组件扫描。自动配置的核心是 @Import 导入 AutoConfigurationImportSelector，读 AutoConfiguration.imports 文件拿到自动配置类，再用 ConditionalOnClass、ConditionalOnMissingBean 这些条件注解判断是否生效。注意 2.7 之后是 imports 文件，不是老的 spring.factories。我项目里封装公共 starter 就是这个套路。」</p><hr><h2 id="_11-springmvc-请求处理流程-★★★" tabindex="-1">11. SpringMVC 请求处理流程 ★★★ <a class="header-anchor" href="#_11-springmvc-请求处理流程-★★★" aria-label="Permalink to &quot;11. SpringMVC 请求处理流程 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 请求先到 DispatcherServlet（前端控制器）→ HandlerMapping 按 URL 找到对应的方法 → HandlerAdapter 执行方法（做参数解析、类型转换、校验）→ 返回 ModelAndView 或者 @ResponseBody 直接写 JSON → ViewResolver 解析视图（返回 JSON 就不走这步）→ 响应。</p><p><strong>我的项目关联</strong> 我们基本都是前后端分离 + REST 接口，所以「@ResponseBody 直接返回 JSON」这条路径最多，ViewResolver 基本用不到。参数解析这块我们在自定义注解上做过扩展，所以知道它由 HandlerAdapter 里的参数解析器负责。</p><p><strong>面试答题话术</strong> 「流程是：请求到 DispatcherServlet，HandlerMapping 找 Handler，HandlerAdapter 执行并处理参数，返回 ModelAndView 或 @ResponseBody 直接写 JSON，最后 ViewResolver 解析视图。前后端分离的项目基本都走 @ResponseBody 返 JSON，视图解析那步用不上。」</p><hr><h2 id="_12-bean-装配注解区别-★★☆" tabindex="-1">12. Bean 装配注解区别 ★★☆ <a class="header-anchor" href="#_12-bean-装配注解区别-★★☆" aria-label="Permalink to &quot;12. Bean 装配注解区别 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> @Autowired 是 Spring 的，默认按类型注入，配合 @Qualifier 按名字。@Resource 是 JDK 标准的，默认按名字，找不到再按类型。@Inject 是 JSR-330 的，跟 @Autowired 差不多。</p><p><strong>我的项目关联</strong> 一句话：同一个类型有多个实现时，我用 @Qualifier 或者 @Resource 按名字指明。这是常规用法，没坑。</p><p><strong>面试答题话术</strong> 「@Autowired 是 Spring 的、默认按类型；@Resource 是 JDK 的、默认按名字找不到再按类型。多个同类型实现时用 @Qualifier 或 @Resource 指定名字。」</p><hr><h2 id="_13-spring、springboot、springcloud-区别-★★★" tabindex="-1">13. Spring、SpringBoot、SpringCloud 区别 ★★★ <a class="header-anchor" href="#_13-spring、springboot、springcloud-区别-★★★" aria-label="Permalink to &quot;13. Spring、SpringBoot、SpringCloud 区别 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> Spring 是地基：提供 IOC 和 AOP，但配置繁琐。SpringBoot 是脚手架：自动配置 + 起步依赖 + 内嵌服务器，让搭建变快。SpringCloud 是微服务工具集：注册中心、配置中心、网关、服务调用、熔断。一句话：Spring 是地基，SpringBoot 是快速建房，SpringCloud 是城市基础设施。</p><p><strong>我的项目关联</strong> 我们的服务全是 SpringBoot 打底，像 yld-tcec 互联互通、yld-admin-service 后台服务都是独立的 SpringBoot 应用，之间再靠远程调用和消息串起来。</p><p><strong>面试答题话术</strong> 「Spring 是核心框架，IOC 加 AOP，但配置麻烦；SpringBoot 是它的封装，自动配置加起步依赖，开箱即用；SpringCloud 是微服务工具集，管注册、配置、网关、调用、熔断。一句话：Spring 是地基，Boot 是快速建房，Cloud 是城市基础设施。我们项目就是 SpringBoot 应用之间靠远程调用和消息串联。」</p><hr><h2 id="_14-spring-security-鉴权链路-jwt-★★★-【简历亮点-高频追问】" tabindex="-1">14. Spring Security 鉴权链路（JWT）★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_14-spring-security-鉴权链路-jwt-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;14. Spring Security 鉴权链路（JWT）★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 基于过滤器链：请求先过认证和授权的过滤器，再进 Controller。JWT 认证流程：请求带 Token → 自定义 JWT 过滤器解析并校验签名和有效期 → 把用户信息塞进 <code>SecurityContextHolder</code> → 后续授权就基于它判断。JWT 是 Header.Payload.Signature 三段 Base64，Payload 只放用户 id、角色这些非敏感信息。</p><p><strong>我的项目关联</strong> 后台管理端和 App 端都是 JWT 鉴权：登录发 token，之后每个请求走 JWT 过滤器。<strong>一个必须讲的坑</strong>：JWT 是无状态的，签出去就收不回，没法主动踢人下线——我们的做法是配合 Redis 存黑名单或者存登录态。另外 JWT 过滤器一定要排在用户名密码过滤器之前，白名单（登录、静态资源）要放行。这是通用坑，我们规范上处理了。</p><p><strong>面试答题话术</strong> 「Security 是过滤器链，请求先认证再授权。JWT 流程是：前端带 token，自定义过滤器解析校验，把用户信息放进 SecurityContextHolder，后面授权基于它。JWT 本身无状态、签了收不回，所以踢下线要配合 Redis 黑名单。还有过滤器顺序要在用户名密码过滤器之前，白名单要放行。项目里后台和 App 都是这套。」</p><hr><h2 id="_15-mybatis-一级缓存、二级缓存-★★★" tabindex="-1">15. MyBatis 一级缓存、二级缓存 ★★★ <a class="header-anchor" href="#_15-mybatis-一级缓存、二级缓存-★★★" aria-label="Permalink to &quot;15. MyBatis 一级缓存、二级缓存 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 一级缓存是 SqlSession 级别，默认开，同一个 SqlSession 内相同查询走缓存；SqlSession 关闭或执行增删改就清空。二级缓存是 Mapper（namespace）级别，跨 SqlSession，需要显式开（<code>cacheEnabled=true</code> + <code>&lt;cache/&gt;</code>），实体要序列化。结论：MyBatis 缓存粒度粗、分布式下容易读到旧数据，所以<strong>我们线上基本关掉二级缓存，用 Redis 做缓存</strong>。</p><p><strong>我的项目关联</strong> 我们直接关二级缓存。原因很直接：服务是多实例部署，二级缓存是「单机」的，A 实例改了数据，B 实例的缓存还是旧的，会读到脏数据。缓存统一交给 Redis，可控、能主动失效。</p><p><strong>面试答题话术</strong> 「一级缓存是 SqlSession 级、默认开，执行增删改或关闭就清；二级缓存是 Mapper 级、跨 SqlSession、要显式开。但二级缓存是单机的，多实例部署会读到脏数据，所以线上我一般关掉，缓存统一用 Redis。项目里就是这么做的。」</p><hr><h2 id="_16-mybatis-执行流程-★★☆" tabindex="-1">16. MyBatis 执行流程 ★★☆ <a class="header-anchor" href="#_16-mybatis-执行流程-★★☆" aria-label="Permalink to &quot;16. MyBatis 执行流程 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 配置阶段解析 XML/注解生成 Configuration 和 MappedStatement；然后开 SqlSession，内部建 Executor；执行时 Mapper 接口的动态代理找到对应的 MappedStatement，Executor 交给 StatementHandler 处理参数、ResultSetHandler 把结果映射成对象。插件（Interceptor）就是在这几个环节做动态代理拦截，分页插件就是这么实现的。</p><p><strong>我的项目关联</strong> 知道流程和「分页插件基于 Interceptor」这个结论就行，不用背源码。我们用的 MyBatis-Plus 分页插件就是这个原理。</p><p><strong>面试答题话术</strong> 「流程是配置解析、开 SqlSession、动态代理找到 MappedStatement、Executor 执行、StatementHandler 处理参数、ResultSetHandler 映射结果。插件是基于 Interceptor 代理这几步，分页插件就是这么做的。」</p><hr><h2 id="_17-mybatis-plus-相比-mybatis-的优势-★★☆" tabindex="-1">17. MyBatis-Plus 相比 MyBatis 的优势 ★★☆ <a class="header-anchor" href="#_17-mybatis-plus-相比-mybatis-的优势-★★☆" aria-label="Permalink to &quot;17. MyBatis-Plus 相比 MyBatis 的优势 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 内置通用 CRUD（BaseMapper）、条件构造器 Wrapper、分页插件、逻辑删除、字段自动填充、代码生成器，省掉大量样板 SQL。本质还是 MyBatis 的增强，底层没变。</p><p><strong>我的项目关联</strong> 我们项目用的就是 MyBatis-Plus，简单单表增删改查直接用 BaseMapper 和 Wrapper，复杂查询才手写 XML。逻辑删除、自动填充创建时间这些也都用上了。</p><p><strong>面试答题话术</strong> 「MP 就是 MyBatis 的增强，内置 CRUD、Wrapper 条件构造器、分页、逻辑删除、自动填充、代码生成器，省样板代码，底层还是 MyBatis。项目里单表操作用它，复杂查询手写 XML。」</p><hr><h2 id="_18-和-区别-必考-★★★" tabindex="-1">18. #{} 和 ${} 区别（必考）★★★ <a class="header-anchor" href="#_18-和-区别-必考-★★★" aria-label="Permalink to &quot;18. #{} 和 ${} 区别（必考）★★★&quot;">​</a></h2><p><strong>通俗理解</strong><code>#{}</code> 是预编译占位符（底层是 PreparedStatement 的 <code>?</code>），参数按值绑定、自动加引号、能防 SQL 注入。<code>${}</code> 是直接字符串拼接，不防注入，只能用在表名、列名这种不能预编译的地方，而且必须做白名单校验。结论一句话：能用 <code>#{}</code> 绝不用 <code>${}</code>。</p><p><strong>我的项目关联</strong> 我们项目规范是禁止 <code>${}</code>，静态扫描会拦。只有极少数动态排序字段（比如后台按哪个字段排序）用 <code>${}</code>，而且字段名必须走白名单校验。这是安全底线。</p><p><strong>面试答题话术</strong> 「#{} 是预编译占位符，参数按值绑定，防注入；${} 是字符串拼接，不防注入。所以能用 #{} 就不用 ${}，只有表名、列名、排序字段这种没法预编译的才用，而且必须白名单校验。项目里我们直接禁止 ${}，静态扫描拦住。」</p><hr><h2 id="_19-spring-中的设计模式-★★★" tabindex="-1">19. Spring 中的设计模式 ★★★ <a class="header-anchor" href="#_19-spring-中的设计模式-★★★" aria-label="Permalink to &quot;19. Spring 中的设计模式 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 工厂（BeanFactory）、单例（默认 Bean）、代理（AOP）、模板方法（JdbcTemplate/RestTemplate）、观察者（ApplicationEvent）、适配器（HandlerAdapter）、策略（资源处理）。重点能展开的是代理模式——AOP 就是它，用来织入事务、日志。</p><p><strong>我的项目关联</strong> 我用得最多的是「模板方法 + 策略」：充电桩不同协议的命令处理，用策略模式按协议类型分发到不同处理器；公共流程用模板方法抽出来，差异部分子类实现。这样加一种新协议只加一个实现类，不动主流程。</p><p><strong>面试答题话术</strong> 「Spring 里常见的：工厂用 BeanFactory，单例是默认 Bean 作用域，代理是 AOP，模板方法在 JdbcTemplate，观察者是事件机制，适配器是 HandlerAdapter。我自己在网关里用策略模式按协议分发处理器，加新协议只加实现类不动主流程。」</p><hr><h2 id="_20-async-失效原因-★★☆" tabindex="-1">20. @Async 失效原因 ★★☆ <a class="header-anchor" href="#_20-async-失效原因-★★☆" aria-label="Permalink to &quot;20. @Async 失效原因 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 跟事务失效一个道理，都是因为「依赖代理」：同类 this 自调用不走代理、方法非 public、类不是 Spring Bean、没开 <code>@EnableAsync</code>。解法也一样：抽到另一个 Bean、注入自身、用 <code>AopContext.currentProxy()</code>。</p><p><strong>我的项目关联</strong> 我们异步任务用线程池 + @Async 都行，但记住「自调用失效」这一条就够。它和 @Transactional 失效是同一类问题，底层都是 AOP 代理。</p><p><strong>面试答题话术</strong> 「@Async 失效原因跟 @Transactional 一样：自调用、非 public、不是 Bean、没开 @EnableAsync。本质是都靠代理，this 调用不走代理。解决就是抽到别的 Bean 或注入自身。」</p><hr><h2 id="_21-springmvc-参数校验、全局异常处理-★★☆" tabindex="-1">21. SpringMVC 参数校验、全局异常处理 ★★☆ <a class="header-anchor" href="#_21-springmvc-参数校验、全局异常处理-★★☆" aria-label="Permalink to &quot;21. SpringMVC 参数校验、全局异常处理 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 参数校验用 <code>@Valid</code>/<code>@Validated</code> 加 <code>@NotNull</code>/<code>@NotBlank</code>/<code>@Size</code>，失败可以全局统一处理。全局异常用 <code>@RestControllerAdvice</code> + <code>@ExceptionHandler</code>，统一返回错误结构，别让异常堆栈直接暴露给前端。</p><p><strong>我的项目关联</strong> 我们统一用 <code>@RestControllerAdvice</code> 做全局异常，所有接口返回统一的 <code>code/message/data</code> 结构，参数校验失败、业务异常、系统异常都在这里收口。这样前端处理统一，也不会把栈信息漏出去。</p><p><strong>面试答题话术</strong> 「参数校验用 @Valid 加注解，失败抛异常。全局异常用 @RestControllerAdvice 加 @ExceptionHandler 统一处理，返回统一结构。项目里所有接口的返回结构、参数校验错误、系统异常都在一个 Advice 里收口，避免把堆栈暴露给前端。」</p><hr><h2 id="_22-spring-cloud-核心组件-★★★" tabindex="-1">22. Spring Cloud 核心组件 ★★★ <a class="header-anchor" href="#_22-spring-cloud-核心组件-★★★" aria-label="Permalink to &quot;22. Spring Cloud 核心组件 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 注册中心（Nacos/Eureka）、配置中心（Nacos Config）、网关（Spring Cloud Gateway）、服务调用（OpenFeign）、熔断限流（Sentinel/Resilience4j）、负载均衡（LoadBalancer）、链路追踪（Sleuth+Zipkin 或 SkyWalking）。Nacos 比 Eureka 强在「注册 + 配置一体，还支持 CP/AP 切换」。</p><p><strong>我的项目关联</strong> 我们的服务是分布式部署的，服务间调用、注册发现、配置管理都是这套。<strong>要说清楚一点</strong>：我们不是那种「重微服务」架构，服务数量有限，所以没用全套 Spring Cloud 组件，主要是按需用的注册和调用，别吹成全套 Cloud 微服务体系。</p><p><strong>面试答题话术</strong> 「核心组件：注册中心、配置中心、网关、服务调用、熔断限流、负载均衡、链路追踪。Nacos 跟 Eureka 比是注册加配置一体，还能切 CP/AP。项目里我用的是注册发现加远程调用为主，没上全套 Cloud，够用就行。」</p><hr><h2 id="_23-网关作用、gateway-过滤器-★★☆" tabindex="-1">23. 网关作用、Gateway 过滤器 ★★☆ <a class="header-anchor" href="#_23-网关作用、gateway-过滤器-★★☆" aria-label="Permalink to &quot;23. 网关作用、Gateway 过滤器 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> API 网关的作用：统一入口、路由转发、鉴权、限流、日志、灰度。Spring Cloud Gateway 基于 WebFlux（响应式、非阻塞），过滤器分全局 GlobalFilter 和局部 GatewayFilter，断言 Predicate 按路径、方法、header 匹配路由。</p><p><strong>我的项目关联</strong><strong>注意别和我们的「协议网关」混了</strong>：Spring Cloud Gateway 是 HTTP 层的 API 网关；我们说的充电桩网关是基于 Netty 的 TCP 长连接网关。面试时要说清这两个是完全不同的东西，不要一被问「网关」就只说 Netty。</p><p><strong>面试答题话术</strong> 「API 网关做统一入口、路由、鉴权、限流。Gateway 基于 WebFlux 是非阻塞的，过滤器分全局和局部，断言按路径方法匹配。这里我要区分一下：Spring Cloud Gateway 是 HTTP 层网关，我们项目里还有个基于 Netty 的 TCP 协议网关接充电桩，两个不是一回事。」</p><hr><h2 id="_24-微服务架构的优缺点-★★☆" tabindex="-1">24. 微服务架构的优缺点 ★★☆ <a class="header-anchor" href="#_24-微服务架构的优缺点-★★☆" aria-label="Permalink to &quot;24. 微服务架构的优缺点 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 优点：独立部署、故障隔离、可独立扩展、技术栈灵活。缺点：分布式复杂度上来了——事务、一致性、网络、链路追踪、运维都变难。业务复杂、团队大才值得拆，小项目别硬上微服务。</p><p><strong>我的项目关联</strong> 我们按业务拆成了后台服务、App 服务、互联互通服务这些，好处是某个服务出问题不至于全挂；代价是跨服务调用和对账一致性要额外处理（我们靠消息、幂等、对账补偿来兜）。</p><p><strong>面试答题话术</strong> 「优点是独立部署、故障隔离、可扩展；缺点是分布式复杂度高，事务、一致性、网络、运维都难。项目里我们按业务拆了后台、App、互联互通几个服务，好处是隔离，代价是跨服务一致性要靠消息、幂等和对账补偿来兜。」</p><hr><h2 id="_25-spring-有哪些模块-★★☆" tabindex="-1">25. Spring 有哪些模块 ★★☆ <a class="header-anchor" href="#_25-spring-有哪些模块-★★☆" aria-label="Permalink to &quot;25. Spring 有哪些模块 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 核心容器（Beans、Core、Context、SpEL，是 IOC 基础）、AOP、数据访问（JDBC、ORM、事务）、Web（MVC、WebFlux）、测试。SpringBoot 和 SpringCloud 都是在它之上的扩展。</p><p><strong>我的项目关联</strong> 一句话：真正的地基是「核心容器 + AOP」，其他都是按需要加。我们主要用 Web（MVC）、数据访问（MyBatis 整合 + 事务）、AOP。</p><p><strong>面试答题话术</strong> 「核心模块是核心容器加 AOP，其他是数据访问、Web、测试。Boot 和 Cloud 都是在 Spring 之上的扩展。项目里主要用 MVC、MyBatis 整合和事务、AOP 这几块。」</p><hr><h2 id="_26-spring-有哪些优点-★★☆" tabindex="-1">26. Spring 有哪些优点 ★★☆ <a class="header-anchor" href="#_26-spring-有哪些优点-★★☆" aria-label="Permalink to &quot;26. Spring 有哪些优点 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 轻量、非侵入（POJO 不用继承 Spring 的类）、IOC 解耦、AOP 解耦横切逻辑、声明式事务、模板类简化开发、生态大、方便测试。</p><p><strong>我的项目关联</strong> 一句话：最实在的两个好处是「声明式事务」和「生态整合」——加个依赖注解就整合好 MyBatis、Redis、Kafka，不用自己搓。</p><p><strong>面试答题话术</strong> 「优点：轻量非侵入、IOC 解耦、AOP 解耦横切逻辑、声明式事务、模板类简化代码、生态大、好测试。最实在的是整合方便，加个 starter 就把 MyBatis、Redis、Kafka 串起来了。」</p><hr><h2 id="_27-xml-时代的自动装配模式-byname-autodetect-等-★☆☆-已过时-一句话" tabindex="-1">27. XML 时代的自动装配模式（byName / autodetect 等）★☆☆（已过时，一句话） <a class="header-anchor" href="#_27-xml-时代的自动装配模式-byname-autodetect-等-★☆☆-已过时-一句话" aria-label="Permalink to &quot;27. XML 时代的自动装配模式（byName / autodetect 等）★☆☆（已过时，一句话）&quot;">​</a></h2><p><strong>通俗理解</strong><code>byName</code>、<code>byType</code>、<code>constructor</code>、<code>autodetect</code> 是 XML 配置时代的自动装配模式，<code>autodetect</code> 早在 Spring 3 就废弃了。现在一律用注解：<code>@Autowired</code> 默认按类型、<code>@Resource</code> 默认按名字。<strong>这条面试基本不问，知道「这是老东西、已被注解取代」就够了。</strong></p><hr><h2 id="_28-springboot-启动流程-★★★" tabindex="-1">28. SpringBoot 启动流程 ★★★ <a class="header-anchor" href="#_28-springboot-启动流程-★★★" aria-label="Permalink to &quot;28. SpringBoot 启动流程 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> main 方法创建 SpringApplication → 推断应用类型（Servlet 还是 Reactive）→ 加载初始化器和监听器 → 准备 Environment（加载配置、命令行参数、profile）→ 创建 ApplicationContext → refresh 刷新（扫描 Bean、执行自动配置）→ 启动内嵌的 Tomcat → 发布 ApplicationReadyEvent。</p><p><strong>我的项目关联</strong> 知道「refresh 阶段才会自动配置、内嵌 Tomcat 是自动配置里创建的」这个结论就行。实际排障时有个用处：启动卡住或 Bean 冲突，看日志基本卡在 refresh 阶段。</p><p><strong>面试答题话术</strong> 「流程是：创建 SpringApplication、推断应用类型、准备 Environment、创建 ApplicationContext、refresh 扫描并自动配置、启动内嵌 Tomcat、发就绪事件。重点知道两件事：自动配置发生在 refresh 阶段，内嵌 Tomcat 也是自动配置里建的。」</p><hr><h2 id="_29-springboot-核心注解-★★★" tabindex="-1">29. SpringBoot 核心注解 ★★★ <a class="header-anchor" href="#_29-springboot-核心注解-★★★" aria-label="Permalink to &quot;29. SpringBoot 核心注解 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><code>@SpringBootApplication</code> = <code>@SpringBootConfiguration</code> + <code>@EnableAutoConfiguration</code> + <code>@ComponentScan</code>。条件装配三件套：<code>@ConditionalOnClass</code>（类在才生效）、<code>@ConditionalOnMissingBean</code>（没有这个 Bean 才生效）、<code>@ConditionalOnProperty</code>（配置满足才生效）。<code>@Configuration</code>+<code>@Bean</code> 用来声明 Bean，<code>@Component/@Service/@Repository/@Controller</code> 靠组件扫描。</p><p><strong>我的项目关联</strong> 我们自定义 starter 或者做条件化配置时就用这三个条件注解，比如「只有当业务方引入了某个依赖、且没自己定义 Bean 时，才注入我们的默认实现」。</p><p><strong>面试答题话术</strong> 「@SpringBootApplication 拆开是配置类、开启自动配置、组件扫描三个。自动配置靠 @Import 导入选择器。条件装配最关键的是 @ConditionalOnClass、@ConditionalOnMissingBean、@ConditionalOnProperty，我们封装 starter 时就靠这三个控制生效条件。」</p><hr><h2 id="_30-mybatis-sqlsession-的线程安全问题-★★★" tabindex="-1">30. MyBatis SqlSession 的线程安全问题 ★★★ <a class="header-anchor" href="#_30-mybatis-sqlsession-的线程安全问题-★★★" aria-label="Permalink to &quot;30. MyBatis SqlSession 的线程安全问题 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> SqlSession 不是线程安全的：它对应一个数据库连接 + 一个一级缓存，多线程共享会互相污染。所以每次操作要用一个新的、用完关闭。跟 Spring 整合后就不用担心了——Mapper 代理是单例，但内部通过 SqlSessionTemplate 用 ThreadLocal 给每个线程绑定独立的 SqlSession。</p><p><strong>我的项目关联</strong> 我们直接用 Spring 整合的 Mapper，从来不手动开 SqlSession，所以这个坑碰不到。但面试问「Mapper 是单例的为什么不冲突」，答「底层 SqlSessionTemplate 用 ThreadLocal 给每个线程独立的 SqlSession」就对了。</p><p><strong>面试答题话术</strong> 「SqlSession 非线程安全，因为它绑定连接和一级缓存，多线程共享会污染。Spring 整合后 Mapper 代理虽然是单例，但底层用 SqlSessionTemplate 加 ThreadLocal，每个线程拿到独立的 SqlSession，所以安全。项目里我们只用 Mapper，不手写 SqlSession。」</p><hr><h2 id="_31-mybatis-的优缺点-★★☆" tabindex="-1">31. MyBatis 的优缺点 ★★☆ <a class="header-anchor" href="#_31-mybatis-的优缺点-★★☆" aria-label="Permalink to &quot;31. MyBatis 的优缺点 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 优点：SQL 和代码分离、可手写复杂 SQL、动态 SQL 灵活、轻量无侵入、插件扩展好。缺点：SQL 依赖数据库方言、迁移要改 SQL、样板代码多、缓存粒度粗、复杂关联还得手写 join。</p><p><strong>我的项目关联</strong> 选它就是看中「SQL 可控」——充电业务里统计、对账、按条件查订单这些复杂查询，要求能精确调优，手写 SQL 比 ORM 生成的更可控。</p><p><strong>面试答题话术</strong> 「MyBatis 优点是 SQL 可控、能写复杂查询和动态 SQL、轻量、插件扩展好；缺点是依赖数据库方言、样板代码多、缓存粒度粗。选它是因为我们业务里对账、统计这种复杂查询要求 SQL 可控、能精确调优。」</p><hr><h2 id="附-一句话速记-可以跳过-★☆☆" tabindex="-1">附：一句话速记（可以跳过 ★☆☆） <a class="header-anchor" href="#附-一句话速记-可以跳过-★☆☆" aria-label="Permalink to &quot;附：一句话速记（可以跳过 ★☆☆）&quot;">​</a></h2><ul><li>Spring Test：<code>@SpringBootTest</code> 起容器、<code>@MockBean</code> 打桩，写集成测试用。</li><li><code>@ControllerAdvice</code> 与 <code>@RestControllerAdvice</code>：后者是前者的 ResponseBody 版本，返回 JSON 用它。</li></ul>',158)]))}const S=e(a,[["render",s]]);export{h as __pageData,S as default};
